from common.handlerKw.kwDecorator import KwDecoratorfrom company.qkl.new.common.api.api_manager import ApiManagerclass SetManager:    @staticmethod    @KwDecorator('SetManager：模拟上报车牌号')    def api_swapFlowTask_cameraSendCarNo(carNo):        data = {            'carNo': carNo        }        return ApiManager.api_swapFlowTask_cameraSendCarNo(data)    @staticmethod    @KwDecorator('SetManager：下控蓝牙连接')    def api_swapFlowTask_manualSendBluetoothStatus_1(vbleMac, mbmuIrk):        data = {            "type": 1,            "vbleMac": vbleMac,            "mbmuIrk": mbmuIrk        }        return ApiManager.api_swapFlowTask_manualSendBluetoothStatus(data)    @staticmethod    @KwDecorator('SetManager：下控蓝牙断开')    def api_swapFlowTask_manualSendBluetoothStatus_2():        data = {            "type": 2        }        return ApiManager.api_swapFlowTask_manualSendBluetoothStatus(data)